import{_ as t,o as r,c as a,a5 as o}from"./chunks/framework.QWVCgkrI.js";const n="/study/images/network/ip-routing-and-ethernet.svg",g=JSON.parse('{"title":"IPルーティングとEthernetフレーム","description":"","frontmatter":{"title":"IPルーティングとEthernetフレーム","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"network","summary":"宛先IPから最長プレフィックス一致で経路を選び、次の機器へEthernetフレームを届ける。ARP、IPv6近隣探索、ホップ制限とtracerouteを扱う。","aliases":["IP routing","ルーティング","Ethernet","MAC address","ARP","Neighbor Discovery","next hop","デフォルトゲートウェイ","最長プレフィックス一致","TTL","Hop Limit","ICMP","tracert"],"verification":"IETFのIP・ARP・IPv6近隣探索のRFCとMicrosoftの資料に照合し、Find-NetRouteをWindowsで実行確認（2026-11-07）"}},"headers":[],"relativePath":"network/ip-routing-and-ethernet.md","filePath":"network/ip-routing-and-ethernet.md"}'),c={name:"network/ip-routing-and-ethernet.md"};function d(i,e,s,h,l,f){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="ipルーティングとethernetフレーム" tabindex="-1">IPルーティングとEthernetフレーム <a class="header-anchor" href="#ipルーティングとethernetフレーム" aria-label="Permalink to &quot;IPルーティングとEthernetフレーム&quot;">​</a></h1><p>アプリがTCPやUDPで通信すると、OSのIP層は<strong>宛先IPをどの経路へ送るか</strong>を判断します。Ethernetを使う区間では、その区間で次に受け取る機器のMACアドレスを宛先にしてフレームを送ります。別のネットワークへ送るときは、IPパケットの宛先と、最初のフレームを受け取る機器が分かれます。<a href="https://datatracker.ietf.org/doc/html/rfc1812#section-5.2.4" target="_blank" rel="noreferrer">IETF RFC 1812 §5.2.4</a> · <a href="/study/network/tcp-sockets.html">TCPのソケット</a> · <a href="/study/network/udp-datagrams.html">UDPのデータグラム</a></p><h2 id="宛先ipから次の送り先を選ぶ" tabindex="-1">宛先IPから次の送り先を選ぶ <a class="header-anchor" href="#宛先ipから次の送り先を選ぶ" aria-label="Permalink to &quot;宛先IPから次の送り先を選ぶ&quot;">​</a></h2><p>例えば送信端末のIPv4アドレスを<code>192.0.2.10/24</code>、ゲートウェイを<code>192.0.2.1</code>とします。<code>/24</code>は先頭24ビットが経路の照合に使われることを表します。簡略化した経路表では、宛先に一致する項目のうち、最も長いプレフィックスを使う項目を選びます。これを<strong>最長プレフィックス一致</strong>と呼びます。IPv4の<code>0.0.0.0/0</code>とIPv6の<code>::/0</code>は、照合する先頭ビットが0個のデフォルト経路です。<a href="https://datatracker.ietf.org/doc/html/rfc1812#section-5.2.4.3" target="_blank" rel="noreferrer">IETF RFC 1812 §5.2.4.3</a> · <a href="https://datatracker.ietf.org/doc/html/rfc4191#section-2.2" target="_blank" rel="noreferrer">IETF RFC 4191 §2.2</a></p><table tabindex="0"><thead><tr><th>この端末の経路表</th><th>次ホップ</th><th>選ばれる例</th></tr></thead><tbody><tr><td><code>192.0.2.0/24</code></td><td>宛先の機器へ直接</td><td><code>192.0.2.20</code>は<code>/24</code>と<code>/0</code>の両方に一致するので<code>/24</code>を使う。</td></tr><tr><td><code>0.0.0.0/0</code></td><td><code>192.0.2.1</code></td><td><code>198.51.100.8</code>はこの表では<code>/0</code>だけに一致する。</td></tr></tbody></table><p>次ホップは、そのリンクで次にパケットを受け取る機器です。宛先へ直接送れる経路なら次ホップは宛先自身です。ゲートウェイを使う経路なら、まずゲートウェイへ送り、そのルーターも自分の経路表で次の区間を決めます。名前で接続するアプリはDNSなどで得たアドレスを使って接続を試みます。経路はその宛先IPに対して選ばれます。例のアドレスは文書用の範囲です。<a href="https://datatracker.ietf.org/doc/html/rfc1812#section-5.2.4.1" target="_blank" rel="noreferrer">IETF RFC 1812 §5.2.4.1</a> · <a href="https://datatracker.ietf.org/doc/html/rfc5737#section-3" target="_blank" rel="noreferrer">IETF RFC 5737 §3</a> · <a href="/study/network/dns-resolution.html">DNSと名前解決</a></p><p>WindowsのPowerShellで<code>Find-NetRoute -RemoteIPAddress 198.51.100.8</code>を実行すると、この文書用アドレスに対して自分の端末が選ぶ経路を照会できます。<code>DestinationPrefix</code>と<code>NextHop</code>の結果は端末の経路表によって変わります。このコマンドはローカルの経路選択を調べるものです。<a href="https://learn.microsoft.com/en-us/powershell/module/nettcpip/find-netroute" target="_blank" rel="noreferrer">MicrosoftのFind-NetRoute</a></p><h2 id="次ホップのipからmacアドレスを調べる" tabindex="-1">次ホップのIPからMACアドレスを調べる <a class="header-anchor" href="#次ホップのipからmacアドレスを調べる" aria-label="Permalink to &quot;次ホップのIPからMACアドレスを調べる&quot;">​</a></h2><p>Ethernetフレームには送信元MAC、宛先MAC、内容の種類を表す欄があり、IPv4を運ぶ場合はその中にIPパケットが入ります。送信端末が<code>198.51.100.8</code>へ送る例では、最初の次ホップは<code>192.0.2.1</code>です。IPv4のEthernetで対応がまだ分からなければ、<strong>ARP</strong>で<code>192.0.2.1</code>のMACアドレスを同じリンクに問い合わせます。受け取った対応はキャッシュでき、次のパケットで再利用できます。<a href="https://datatracker.ietf.org/doc/html/rfc894" target="_blank" rel="noreferrer">IETF RFC 894のEthernetへの格納</a> · <a href="https://datatracker.ietf.org/doc/html/rfc826" target="_blank" rel="noreferrer">IETF RFC 826のARP</a></p><p>IPv6では、<strong>近隣探索</strong>（Neighbor Discovery）がリンク上のアドレス解決を行います。例えば未解決の相手にICMPv6のNeighbor Solicitationを送り、Neighbor Advertisementでリンク層のアドレスを得ます。IPv6端末はRouter Advertisementなどから、どのプレフィックスを直接届けられる範囲として扱うかや、どのルーターを使えるかも学びます。<a href="https://datatracker.ietf.org/doc/html/rfc4861#section-5.2" target="_blank" rel="noreferrer">IETF RFC 4861 §5.2</a> · <a href="https://datatracker.ietf.org/doc/html/rfc4861#section-7.2" target="_blank" rel="noreferrer">同 §7.2</a></p><figure class="study-figure"><img src="'+n+'" alt="送信端末192.0.2.10からルーター192.0.2.1を経て、受信端末198.51.100.8へ送る。最初のEthernetフレームのMACはAからR1、次はルーターの別の口のR2からB。両リンクで送信元IPは192.0.2.10、宛先IPは198.51.100.8。ルーターでTTLが64から63へ減る。" width="760" height="388" loading="lazy"><figcaption>アドレス変換を行わないIPv4転送の例です。ルーターは受け取ったIPパケットを、次のリンクの宛先に合わせたフレームで送ります。<a href="/study/images/network/ip-routing-and-ethernet.svg" target="_blank" rel="noopener noreferrer">二つのリンクの図を拡大</a></figcaption></figure><p>図では、最初のEthernetフレームは送信端末のMAC AからルーターのMAC R1へ届きます。ルーターの向こう側では、出口のMAC R2から受信端末のMAC Bへ、新しいフレームを送ります。アドレス変換（NAT）を行わないこの例では、IPヘッダーの送信元と宛先は両区間で同じです。転送時にはIPv4のTTLが変わります。<a href="https://datatracker.ietf.org/doc/html/rfc1812#section-5.2.1" target="_blank" rel="noreferrer">IETF RFC 1812 §5.2.1</a> · <a href="https://datatracker.ietf.org/doc/html/rfc3022#section-2" target="_blank" rel="noreferrer">IETF RFC 3022 §2</a></p><h2 id="ホップの上限とtracerouteの応答" tabindex="-1">ホップの上限とtracerouteの応答 <a class="header-anchor" href="#ホップの上限とtracerouteの応答" aria-label="Permalink to &quot;ホップの上限とtracerouteの応答&quot;">​</a></h2><p>IPv4の<strong>TTL</strong>は転送時にルーターが少なくとも1減らし、IPv6の<strong>Hop Limit</strong>は転送ごとに1減ります。上限に達して転送できなくなると、ルーターはパケットを破棄し、条件に応じて送信元へICMPのTime Exceededを返します。この仕組みは、経路にループがある場合にもパケットが回り続けるのを防ぎます。<a href="https://datatracker.ietf.org/doc/html/rfc1812#section-5.3.1" target="_blank" rel="noreferrer">IETF RFC 1812 §5.3.1</a> · <a href="https://datatracker.ietf.org/doc/html/rfc8200#section-3" target="_blank" rel="noreferrer">IETF RFC 8200 §3</a> · <a href="https://datatracker.ietf.org/doc/html/rfc4443#section-3.3" target="_blank" rel="noreferrer">IETF RFC 4443 §3.3</a></p><p>Windowsの<code>tracert</code>は、TTLやHop Limitを1から増やしながらICMPの探査パケットを送り、Time Exceededや宛先からの応答を記録します。<code>*</code>は、その探査への応答を制限時間内に受け取れなかった印です。ルーターがICMP応答を制限する場合や、計測中に経路が変わる場合があります。表示する時間は探査を送ってから応答が戻るまでなので、往路と復路の待ち時間を含みます。<a href="https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/tracert" target="_blank" rel="noreferrer">Microsoftのtracert</a> · <a href="https://datatracker.ietf.org/doc/html/rfc1812#section-4.3.2.8" target="_blank" rel="noreferrer">IETF RFC 1812 §4.3.2.8</a> · <a href="https://datatracker.ietf.org/doc/html/rfc1393#section-1" target="_blank" rel="noreferrer">IETF RFC 1393 §1の探査手順</a> · <a href="/study/network/latency-throughput-and-queues.html">遅延・スループットと待ち行列</a></p>',15)])])}const m=t(c,[["render",d]]);export{g as __pageData,m as default};
